/* All Languages Dictionary — language registry, persistence and switching.
 *
 * Two tiers of language:
 *   LOCAL   a hand-built dictionary file ships with the app: every word has a
 *           curated headword and a worked example in both English and the
 *           target language.
 *   REMOTE  any other language Google Translate supports. There is no local
 *           file, so lookups are translated live and examples are generated by
 *           the AI tutor endpoint.
 *
 * Everything user-facing reads its language name from here, so no screen has to
 * hardcode a language again.
 */
(function (global) {
  'use strict';

  var STORAGE_KEY = 'alldic_lang';

  // id -> definition. `file` is relative to the site root; `css` is the class
  // infix used inside that dictionary file (class=<css>_text / class=in_<css>).
  var LOCAL = {
    bemba:      { code: 'bem', label: 'Bemba',      native: 'Ichibemba', css: 'bemba',      file: 'dictionary/bemba_dictionary.js' },
    nyanja:     { code: 'ny',  label: 'Nyanja',     native: 'Chinyanja', css: 'nyanja',     file: 'dictionary/nyanja_dictionary.js' },
    french:     { code: 'fr',  label: 'French',     native: 'Français',  css: 'french',     file: 'dictionary/french_dictionary.js' },
    portuguese: { code: 'pt',  label: 'Portuguese', native: 'Português', css: 'portuguese', file: 'dictionary/portuguese.js' },
    spanish:    { code: 'es',  label: 'Spanish',    native: 'Español',   css: 'spanish',    file: 'dictionary/spanish_dictionary.js' },
    swahili:    { code: 'sw',  label: 'Swahili',    native: 'Kiswahili', css: 'swahili',    file: 'dictionary/swahili_dictionary.js' },
    zulu:       { code: 'zu',  label: 'Zulu',       native: 'isiZulu',   css: 'zulu',       file: 'dictionary/zulu_dictionary.js' }
  };

  // Google Translate's supported set, minus the ones already covered above.
  var REMOTE = [
    ['af', 'Afrikaans'], ['sq', 'Albanian'], ['am', 'Amharic'], ['ar', 'Arabic'],
    ['hy', 'Armenian'], ['az', 'Azerbaijani'], ['eu', 'Basque'], ['be', 'Belarusian'],
    ['bn', 'Bengali'], ['bs', 'Bosnian'], ['bg', 'Bulgarian'], ['ca', 'Catalan'],
    ['ceb', 'Cebuano'], ['zh-CN', 'Chinese (Simplified)'], ['zh-TW', 'Chinese (Traditional)'],
    ['co', 'Corsican'], ['hr', 'Croatian'], ['cs', 'Czech'], ['da', 'Danish'],
    ['nl', 'Dutch'], ['eo', 'Esperanto'], ['et', 'Estonian'], ['fi', 'Finnish'],
    ['fy', 'Frisian'], ['gl', 'Galician'], ['ka', 'Georgian'], ['de', 'German'],
    ['el', 'Greek'], ['gu', 'Gujarati'], ['ht', 'Haitian Creole'], ['ha', 'Hausa'],
    ['haw', 'Hawaiian'], ['he', 'Hebrew'], ['hi', 'Hindi'], ['hmn', 'Hmong'],
    ['hu', 'Hungarian'], ['is', 'Icelandic'], ['ig', 'Igbo'], ['id', 'Indonesian'],
    ['ga', 'Irish'], ['it', 'Italian'], ['ja', 'Japanese'], ['jv', 'Javanese'],
    ['kn', 'Kannada'], ['kk', 'Kazakh'], ['km', 'Khmer'], ['rw', 'Kinyarwanda'],
    ['ko', 'Korean'], ['ku', 'Kurdish'], ['ky', 'Kyrgyz'], ['lo', 'Lao'],
    ['la', 'Latin'], ['lv', 'Latvian'], ['lt', 'Lithuanian'], ['lb', 'Luxembourgish'],
    ['mk', 'Macedonian'], ['mg', 'Malagasy'], ['ms', 'Malay'], ['ml', 'Malayalam'],
    ['mt', 'Maltese'], ['mi', 'Maori'], ['mr', 'Marathi'], ['mn', 'Mongolian'],
    ['my', 'Myanmar (Burmese)'], ['ne', 'Nepali'], ['no', 'Norwegian'], ['or', 'Odia (Oriya)'],
    ['ps', 'Pashto'], ['fa', 'Persian'], ['pl', 'Polish'], ['pa', 'Punjabi'],
    ['ro', 'Romanian'], ['ru', 'Russian'], ['sm', 'Samoan'], ['gd', 'Scots Gaelic'],
    ['sr', 'Serbian'], ['st', 'Sesotho'], ['sn', 'Shona'], ['sd', 'Sindhi'],
    ['si', 'Sinhala'], ['sk', 'Slovak'], ['sl', 'Slovenian'], ['so', 'Somali'],
    ['su', 'Sundanese'], ['sv', 'Swedish'], ['tl', 'Tagalog (Filipino)'], ['tg', 'Tajik'],
    ['ta', 'Tamil'], ['tt', 'Tatar'], ['te', 'Telugu'], ['th', 'Thai'],
    ['tr', 'Turkish'], ['tk', 'Turkmen'], ['uk', 'Ukrainian'], ['ur', 'Urdu'],
    ['ug', 'Uyghur'], ['uz', 'Uzbek'], ['vi', 'Vietnamese'], ['cy', 'Welsh'],
    ['xh', 'Xhosa'], ['yi', 'Yiddish'], ['yo', 'Yoruba']
  ];

  function remoteDef(code, label) {
    return { code: code, label: label, native: label, css: null, file: null, remote: true };
  }

  // Every selectable language, locals first (they have real dictionaries).
  function all() {
    var out = [];
    Object.keys(LOCAL).forEach(function (id) {
      var d = LOCAL[id];
      out.push({ id: id, code: d.code, label: d.label, native: d.native, local: true });
    });
    REMOTE.forEach(function (r) {
      out.push({ id: r[0], code: r[0], label: r[1], native: r[1], local: false });
    });
    return out;
  }

  // Accepts an id ("french"), a Google Translate code ("fr") or a display name
  // ("French"). A built-in language is reachable by its code as well as its id,
  // so a link written either way lands on the same dictionary.
  function find(id) {
    if (!id) return null;
    var key = String(id).trim();
    var lower = key.toLowerCase();

    if (LOCAL[lower]) {
      var d = LOCAL[lower];
      return { id: lower, code: d.code, label: d.label, native: d.native, css: d.css, file: d.file, local: true };
    }
    // Built-in languages by their translate code or English name.
    var ids = Object.keys(LOCAL);
    for (var j = 0; j < ids.length; j++) {
      var ld = LOCAL[ids[j]];
      if (ld.code.toLowerCase() === lower || ld.label.toLowerCase() === lower) {
        return { id: ids[j], code: ld.code, label: ld.label, native: ld.native, css: ld.css, file: ld.file, local: true };
      }
    }
    // Remote languages are keyed by their translate code; match the name too.
    // Several labels carry a parenthetical variant — "Chinese (Simplified)",
    // "Myanmar (Burmese)", "Tagalog (Filipino)" — and a link will almost always
    // use the bare name, so the part before the bracket counts as a match. The
    // first listed variant wins, which makes ?lang=Chinese mean Simplified.
    for (var i = 0; i < REMOTE.length; i++) {
      var label = REMOTE[i][1].toLowerCase();
      var bare = label.split('(')[0].trim();
      if (REMOTE[i][0].toLowerCase() === lower || label === lower || bare === lower) {
        var r = remoteDef(REMOTE[i][0], REMOTE[i][1]);
        r.id = REMOTE[i][0];
        r.local = false;
        return r;
      }
    }
    return null;
  }

  var _active = null;

  function active() {
    if (_active) return _active;

    // ?lang=french (or the shorter ?l=french) wins over the stored choice and
    // then becomes the stored choice, so a shared link opens in the language it
    // was shared in and stays there on the next visit.
    //
    // find() accepts the id, the Google Translate code or the English name, so
    // ?lang=nyanja, ?lang=ny and ?lang=Nyanja all land on the same dictionary.
    var fromUrl = null;
    try {
      var params = new URLSearchParams(global.location.search);
      var q = params.get('lang') || params.get('l');
      if (q) fromUrl = find(q.toLowerCase());
    } catch (e) {}
    if (fromUrl) {
      _active = fromUrl;
      try { localStorage.setItem(STORAGE_KEY, fromUrl.id); } catch (e2) {}
      return _active;
    }

    var saved = null;
    try { saved = localStorage.getItem(STORAGE_KEY); } catch (e) {}
    _active = find(saved) || null;
    return _active;
  }

  function hasChosen() {
    return !!active();
  }

  function setActive(id, opts) {
    var def = find(id);
    if (!def) return null;
    _active = def;
    try { localStorage.setItem(STORAGE_KEY, def.id); } catch (e) {}
    applyBranding();
    if (!opts || opts.reload !== false) {
      // A different dictionary file means a different global `dictionary`
      // object and a rebuilt word list; reloading is far safer than trying to
      // tear down every cached index in the page.
      //
      // The ?lang= / ?l= parameter outranks the stored choice, so reloading with
      // it still in the address bar would snap straight back to the language in
      // the link. Drop it first, so picking a language always wins.
      location.replace(urlWithoutLangParam());
    }
    return def;
  }

  // Current URL minus the language parameters, preserving anything else.
  function urlWithoutLangParam() {
    try {
      var u = new URL(global.location.href);
      if (!u.searchParams.has('lang') && !u.searchParams.has('l')) return u.href;
      u.searchParams.delete('lang');
      u.searchParams.delete('l');
      // Avoid leaving a bare "?" behind.
      return u.pathname + (u.searchParams.toString() ? '?' + u.searchParams.toString() : '') + u.hash;
    } catch (e) {
      return global.location.pathname;
    }
  }

  function label() { var a = active(); return a ? a.label : 'your language'; }
  function code() { var a = active(); return a ? a.code : 'en'; }
  function isLocal() { var a = active(); return !!(a && a.local); }

  /* ---- dictionary entry normalisation ---------------------------------- */

  // Dictionary files tag their content per language (class=french_text,
  // class=in_zulu, ...). Rewriting those to fixed class names on the way in
  // means every consumer — CSS, search, quiz, the API app — can be written once
  // and keep working when a new language file is dropped in.
  var CLASS_TEXT = 'target_text';
  var CLASS_BLOCK = 'in_target';

  function normalise(html) {
    if (!html) return html;
    return String(html)
      .replace(/class=(["']?)([a-z]+)_text\1/gi, 'class=$1' + CLASS_TEXT + '$1')
      .replace(/class=(["']?)in_(?!english\b)([a-z]+)\1/gi, 'class=$1' + CLASS_BLOCK + '$1');
  }

  // Pulls the headword out of an entry, whatever language tagged it.
  function headwordOf(html) {
    if (!html) return '';
    var m = String(html).match(/class=["']?(?:[a-z]+_text|target_text)["']?>([^<]*)</i);
    return m ? m[1].trim() : '';
  }

  /* ---- branding -------------------------------------------------------- */

  // Any element carrying data-lang-name has its text replaced with the active
  // language; data-lang-tmpl does the same inside a template string using {L}.
  function applyBranding() {
    var name = label();
    var doc = global.document;
    if (!doc) return;

    var els = doc.querySelectorAll('[data-lang-name]');
    for (var i = 0; i < els.length; i++) els[i].textContent = name;

    var tmpl = doc.querySelectorAll('[data-lang-tmpl]');
    for (var j = 0; j < tmpl.length; j++) {
      tmpl[j].innerHTML = tmpl[j].getAttribute('data-lang-tmpl').split('{L}').join(name);
    }

    if (doc.title) doc.title = doc.title.replace(/^English into .+? dictionary/, 'English into ' + name + ' dictionary');
    var desc = doc.querySelector('meta[name="description"]');
    if (desc) desc.setAttribute('content', 'This dictionary translates english words into ' + name + ' with examples and quiz.');

    var sel = doc.getElementById('lang-current');
    if (sel) sel.textContent = name;

    var search = doc.getElementById('search');
    if (search) search.placeholder = 'Search in english or ' + name.toLowerCase() + '...';
  }

  global.AllDic = {
    STORAGE_KEY: STORAGE_KEY,
    LOCAL: LOCAL,
    REMOTE: REMOTE,
    all: all,
    find: find,
    active: active,
    hasChosen: hasChosen,
    setActive: setActive,
    label: label,
    code: code,
    isLocal: isLocal,
    normalise: normalise,
    headwordOf: headwordOf,
    applyBranding: applyBranding,
    CLASS_TEXT: CLASS_TEXT,
    CLASS_BLOCK: CLASS_BLOCK
  };
})(window);
